import {ATLAS_ADDITIONS} from './discoveries-catalog.js?v=2026.11.14-harbor-chart';
// Geographic context for the catalog. Sources for real sites and species are listed on the cards.
const records={
 'ruin-azores':['포르투갈 아소르스 제도, 테르세이라섬의 앙그라 두 에루이즈무','유럽과 아프리카·아메리카를 오가는 선단이 대서양을 건너며 이 항구에 들렀어요. 만의 입구를 지키는 요새들은 항구를 보급과 방어에 어떻게 활용했는지 보여 줍니다.'],
 'ruin-carthage':['튀니지 튀니스만 북쪽, 카르타고','카르타고는 페니키아인들이 세운 도시에서 지중해의 주요 교역 중심지로 성장했어요. 옛 도시가 파괴된 뒤 같은 곳에 로마 도시가 들어섰기 때문에, 유적에는 서로 다른 시대의 흔적이 남아 있어요.'],
 'ruin-kilwa':['탄자니아 남부 해안 앞 킬와 키시와니섬','킬와의 상인들은 동아프리카의 금과 인도양 건너편의 도자기 등을 거래했어요. 섬의 모스크와 교역 흔적은 스와힐리 해안 도시들이 어떻게 멀리 떨어진 시장을 연결했는지 보여 줍니다.'],
 'ruin-mahabalipuram':['인도 남동부 타밀나두주, 코로만델 해안','마하발리푸람은 팔라바 왕조의 항구 도시였어요. 이곳에는 바위를 파서 만든 사원과 돌을 쌓아 지은 사원이 함께 남아 있어요. 해안 사원의 탑과 주변 바위 조각을 비교해 보세요.'],
 'ruin-anse':['캐나다 뉴펀들랜드섬 북단, 벨아일 해협','11세기 무렵 북유럽 항해자들이 대서양을 건너 이곳에 머물렀어요. 목재 골조에 잔디와 토탄을 덮은 건물과 철 가공 흔적이 남아 있어, 선원들이 육지에서 어떻게 생활했는지 짐작하게 합니다.'],
 'ruin-rapanui':['칠레 라파누이섬, 남동태평양','모아이는 라파누이 사람들이 만든 거대한 석상이에요. 많은 석상이 의례용 단인 아후에 놓였고, 라노라라쿠 채석장에는 작업이 끝나지 않은 석상도 남아 있어요.'],
 'ruin-nanmadol':['미크로네시아 연방 폰페이섬 남동쪽 연안','난마돌은 산호초 위에 조성한 인공 섬들을 수로로 연결한 유적이에요. 검은 현무암을 쌓은 건축과 수로를 보면 바닷물이 드나드는 곳을 의례와 정치의 중심지로 활용한 방식을 알 수 있어요.'],
 'ruin-sganggwaay':['캐나다 브리티시컬럼비아주 하이다과이 남쪽','큰 삼나무 집터와 기념·장례 기둥이 남아 있는 하이다 마을이에요. 이 유적은 해안에 기반을 둔 하이다 사람들의 예술과 사회를 보여 줍니다. 하이다의 문화는 오늘날에도 이어지고 있어요.'],
 'ruin-fortjesus':['케냐 몸바사섬, 옛 항구 입구','포르투갈은 몸바사 항구를 통제하기 위해 1593~1596년에 이 요새를 세웠어요. 바다로 돌출된 산호암 위의 성벽과 여러 보루는 항구 입구를 내려다보도록 배치되었어요.'],
 'ruin-skellig':['아일랜드 케리주 서쪽 대서양의 스켈리그 미할섬','가파른 바위섬에 중세 수도사들이 세운 돌 오두막과 계단이 남아 있어요. 자연 지형을 깎거나 돌을 쌓아 좁은 평지를 만들고 그 위에 생활 공간을 마련했어요.'],
 'ruin-butrint':['알바니아 남부 사란다 인근, 이오니아해 접근 수역','부트린트에는 그리스 식민도시와 로마 도시를 비롯한 여러 시대의 건물이 남아 있어요. 극장과 성벽이 서로 다른 시기에 만들어졌다는 점에서 한 도시의 오랜 변화를 읽을 수 있어요.'],
 'ruin-galle':['스리랑카 남서해안 갈레','갈레는 인도양에 열린 항구 도시예요. 바닷가 성벽은 네덜란드 식민기에 확장됐고, 성 안쪽 거리에는 유럽의 건축 방식과 남아시아의 기후에 맞춘 건축이 함께 남아 있어요.'],
 'ruin-mozambique-island':['모잠비크 북부 해안 앞 모잠비크섬','이 섬은 인도양을 오가는 배가 들르던 교역 거점이었어요. 요새와 석조 건물, 섬의 여러 주거 양식을 보면 해상 교역이 한 도시의 모습을 어떻게 바꿨는지 알 수 있어요.'],
 'ruin-portobelo':['파나마 북부 카리브해 연안 포르토벨로만','포르토벨로는 스페인 식민기에 아메리카의 화물이 지협을 건너 카리브해 배에 실리던 항구였어요. 만 주위의 요새들은 육상 수송로와 바닷길이 만나는 지점을 지켰습니다.'],
 'ruin-goree':['세네갈 다카르 앞 대서양의 고레섬','고레섬은 대서양 노예무역과 강제 이주의 역사를 기억하는 장소예요. 오늘날 남은 건축과 기념 공간은 바닷길이 교역과 교류뿐 아니라 착취의 통로이기도 했다는 사실을 돌아보게 합니다.'],
 'animal-penguin-africa':['남아프리카공화국 케이프반도 볼더스 해안','아프리카펭귄은 날개를 지느러미처럼 써서 물속에서 먹이를 쫓아요. 남아프리카의 바위 해안에서도 볼 수 있어, 펭귄이 모두 남극에 산다는 생각을 바꿔 주는 종입니다.'],
 'animal-seal-med':['지중해와 동부 대서양 해안','지중해몽크물범은 바다에서 먹이를 찾고, 사람이 드나들기 어려운 해안 동굴에서 쉬거나 새끼를 낳기도 해요. 동굴은 산란장이 아니라 포유류의 휴식·번식 공간이에요.'],
 'animal-otter':['미국 알래스카 남부의 북태평양 연안','해달은 두꺼운 털로 체온을 유지하는 해양 포유류예요. 등을 물에 대고 떠서 먹이를 먹으며, 조개 같은 단단한 먹이를 열 때 돌을 도구로 쓰기도 해요.'],
 'animal-whaleshark':['필리핀 루손섬 남부 돈솔 앞바다','고래상어는 이름에 고래가 들어가지만 상어에 속하는 물고기예요. 입으로 물을 받아 작은 먹이를 걸러 먹어요. 몸의 밝은 반점은 물속에서도 모습을 알아보는 단서가 됩니다.'],
 'animal-iguana':['에콰도르 갈라파고스 제도','바다이구아나는 해안 바위에서 쉬다가 물에 들어가 해조류를 먹어요. 검은 용암 해안에서 몸을 덥히는 모습과 물속에서 헤엄치는 모습을 비교해 보세요.'],
 'animal-hector':['뉴질랜드 남섬 주변의 연안','헥터돌고래는 작은 몸과 둥근 등지느러미가 특징이에요. 뾰족한 등지느러미가 익숙하다면 이 종의 둥근 윤곽이 좋은 관찰 단서가 됩니다.'],
 'animal-seal-hawaii':['미국 하와이 제도의 연안','하와이몽크물범은 바다에서 먹이를 찾고, 모래 해변이나 바위에 올라와 쉬어요. 육지에서 쉬는 모습도 정상 행동이므로 멀리서 관찰하는 것이 중요해요.'],
 'animal-penguin-nz':['뉴질랜드 남섬 오타고 일대의 해안','눈 주위에서 머리 뒤쪽으로 이어지는 노란 띠가 이름의 유래예요. 마오리 이름은 호이호예요. 바다에서 먹이를 구하고 육지에서 번식하는 생활을 합니다.'],
 'animal-gray-whale':['멕시코 바하칼리포르니아 연안의 석호','귀신고래는 북쪽의 먹이터와 따뜻한 번식 해역 사이를 오가요. 등지느러미 대신 등과 꼬리 사이에 작은 돌기가 이어지고, 몸에는 얼룩처럼 보이는 무늬가 있어요.'],
 'animal-manatee':['미국 플로리다의 하구와 얕은 바다','매너티는 물속 식물을 먹는 포유류예요. 플로리다의 매너티는 넓고 둥근 노 모양 꼬리를 지녀, 꼬리가 두 갈래인 듀공과 비교해 볼 수 있어요.'],
 'animal-dugong':['호주 북동부 산호해, 그레이트배리어리프 주변','듀공은 얕은 바다의 해초밭에서 풀을 뜯어요. 두 갈래 꼬리와 아래로 향한 입이 특징입니다. 산호초 가까이 보이더라도 주된 먹이터는 해초가 자라는 바닥이에요.'],
 'animal-green-turtle':['미국 하와이 제도 주변의 바다','푸른바다거북은 하와이에서 호누라고도 불러요. 다 자란 개체는 해초와 조류를 많이 먹으며, 산란할 때는 모래 해변으로 올라옵니다.'],
 'animal-humboldt':['페루와 칠레의 태평양 해안','훔볼트펭귄의 서식지는 차가운 훔볼트 해류의 영향을 받아요. 따뜻한 위도에 있는 해안에서도 해류가 생물의 분포를 바꿀 수 있다는 사례예요.'],
 'animal-orca':['캐나다 브리티시컬럼비아와 미국 워싱턴주 사이의 살리시해','범고래는 돌고래과에 속해요. 살리시해의 남부 정주형 무리는 연어를 주요 먹이로 삼아요. 같은 범고래라도 집단에 따라 먹이와 사냥 방식이 달라집니다.'],
 'relic-compass':['이베리아반도 대서양 연안','자침이 가리키는 방향으로 배의 진행 방향을 확인하는 도구예요. 나침반만으로는 현재 위치를 알 수 없어서 해도나 다른 관측과 함께 사용했어요.'],
 'relic-chart':['카보베르데 제도 주변','이 조각에는 해안선과 항로를 따라가는 선이 남아 있어요. 해도를 볼 때는 해안의 모양, 항구, 바다의 깊이를 알려 주는 표기를 구분해 보면 좋아요.'],
 'relic-astrolabe':['프랑스와 이베리아반도 사이의 비스케이만','그림은 태양이나 별이 수평선에서 얼마나 높은지 재는 항해용 아스트롤라베에서 착안했어요. 나침반이 방향을 재는 도구라면, 이 도구는 각도를 재는 데 쓰였어요.'],
 'relic-amphora':['그리스·튀르키예 사이 에게해','양손잡이가 달린 항아리의 모습에서 착안한 물품이에요. 손잡이, 목의 너비, 바닥 모양을 살펴보면 배에 싣거나 내용물을 꺼내기 편하도록 어떤 형태를 골랐을지 생각해 볼 수 있어요.'],
 'relic-seal':['인도 동쪽과 방글라데시 남쪽의 벵골만','그림의 인장은 상인이 화물에 자신의 표시를 남긴다는 이야기에서 출발했어요. 표시가 복잡한 문장 대신 짧은 문양으로 되어 있는 이유를 상상해 보세요.'],
 'relic-bell':['카리브해','가상의 배에 매달렸던 청동 종이에요. 멀리서도 들리는 종소리는 글이나 몸짓을 보기 어려운 배 위에서 신호를 전하는 방법이 될 수 있어요.'],
 'relic-carving':['남아메리카 남부 파타고니아 연안','파도에 닳은 나무에 소용돌이 모양을 새겼어요. 그림의 문양은 창작이므로 특정 공동체의 조각 양식이나 실제 유물의 출처를 나타내지 않아요.'],
 'relic-pendant':['브라질의 아마존강 유역','돌에 구멍을 뚫어 끈을 통과시킨 가상 장신구예요. 구멍 주변이 매끈해지는 모습을 보면 물건이 어떻게 사용됐을지 추리해 볼 수 있어요.'],
 'relic-alaska-token':['알래스카만','표면에 배 그림이 새겨진 가상 금속 패예요. 바닷물과 모래에 오래 닿은 물건에서는 표면이 닳거나 부식되어 원래 문양의 일부만 남을 수 있어요.'],
 'relic-pacific-chart':['북아메리카 서안의 북태평양','해도에서 남은 해안선과 끊긴 항로를 찾는 수집 기록이에요. 일부분만 남은 지도로는 현재 위치나 안전한 항로를 단정하기 어렵다는 점을 보여 줍니다.'],
 'relic-amazon-weight':['아마존강 하구권','물건과 저울추의 균형으로 무게를 비교한다는 설정이에요. 같은 상품을 거래할 때 상인들이 왜 공통된 무게 기준을 필요로 했는지 생각해 볼 수 있어요.'],
 'relic-andean-pottery':['남아메리카 서해안의 태평양','계단 모양 문양이 남은 가상의 도기 조각이에요. 재질이나 문양은 물건을 비교하는 단서가 되지만, 조각 하나만으로 제작 장소를 단정할 수는 없어요.'],
 'relic-timor-tool':['티모르섬과 호주 북부 사이의 티모르해','움직이는 자와 둥근 눈금이 달린 가상 관측 도구예요. 둥근 눈금은 길이보다 각도를 기록하기 알맞다는 점을 그림에서 비교해 볼 수 있어요.'],
 'relic-micronesia-marker':['서태평양 미크로네시아 해역','가상의 항해자가 사용하던 나무 표식이에요. 실제 미크로네시아의 전통 항해법을 재현한 물건은 아니며, 조각 모양과 묶는 방식은 게임 설정이에요.'],
 'relic-kuril':['일본 홋카이도 북동쪽 쿠릴 열도 주변','물결이 새겨진 가상 표식이에요. 그림에는 화산섬의 검은 해변과 거친 바다가 함께 등장해, 항로의 환경과 물건의 마모를 연결해 살펴볼 수 있어요.'],
 'relic-red-sea':['아프리카 북동부와 아라비아반도 사이의 홍해','눈금과 직선을 이용하는 가상의 황동 자예요. 지도 위에서 선을 긋는 용도와 실제 바다에서 방위를 재는 용도가 어떻게 다른지 비교해 보세요.'],
 'relic-suriname':['남아메리카 북동부 기아나 해안','푸른 유약과 문양이 남은 가상의 조각이에요. 그림처럼 하구에 떠밀려온 물건의 발견 장소가 그 물건을 만든 장소와 같다고 볼 수는 없어요.'],
 'treasure-azores':['북대서양 아소르스 제도 바깥바다','쇠 띠와 자물쇠로 나무판을 고정한 가상의 상자예요. 소금기와 습기가 많은 바다에서는 금속과 나무가 서로 다른 방식으로 닳는 모습을 살펴볼 수 있어요.'],
 'treasure-gulf':['멕시코만','표류선에서 흘러나왔다는 설정의 동전 주머니예요. 서로 다른 크기와 문양의 동전을 보며 여러 항구를 오가는 상인이 어떻게 값을 비교했을지 생각해 보세요.'],
 'treasure-madagascar':['마다가스카르 주변의 인도양 연안','나무 상자 안에 진주를 보관했다는 창작 기록이에요. 그림에서 진주의 둥근 표면과 금속 장식의 반짝임을 비교해 보세요. 특정 진주 산지를 가리키지는 않아요.'],
 'treasure-malacca':['말레이반도와 수마트라섬 사이 말라카 해협','인도양과 동남아시아 바닷길이 만나는 해협을 배경으로 만든 상자예요. 좁은 해협을 지나는 선박과 항구의 교역이 어떻게 연결되는지 살펴볼 수 있어요.'],
 'treasure-namib':['나미비아의 나미브 사막과 대서양이 만나는 해안','바람이 모래를 바닷가로 옮겨 상자 일부를 덮었다는 창작 장면이에요. 사막과 바다가 가까이 만날 때 생기는 해안 풍경을 배경으로 삼았습니다.'],
 'treasure-atacama':['칠레 북부 아타카마 사막의 태평양 연안','마른 바닷가 풍경을 배경으로 한 가상 보물지도예요. 해안의 모양이 보이더라도 거리나 방향의 기준이 없으면 지도를 실제 항로에 쓰기 어려워요.'],
 'treasure-andaman':['인도양 동쪽 안다만 제도 주변','섬 사이에서 찾았다는 가상의 보석함이에요. 섬이 많은 해역의 지도에서는 큰 섬의 윤곽과 그 사이의 좁은 통로를 구분해 보는 것이 좋아요.'],
 'treasure-pacific':['중앙 태평양','별 모양 장식은 가상의 표류 상자에 붙인 무늬예요. 대양의 그림을 보며 육지가 보이지 않을 때 항해자가 어떤 관측과 기록을 활용했을지 생각해 보세요.'],
 'treasure-faroe':['아이슬란드와 스코틀랜드 사이의 페로 제도','밀랍으로 봉인한 상자가 북대서양에 떠밀려왔다는 이야기예요. 밀랍 자국은 누군가 상자를 열었는지 확인하는 표시로 상상해 볼 수 있어요.'],
 'treasure-socotra':['아라비아해 서쪽, 아덴만 입구의 소코트라섬','아덴만과 인도양이 만나는 곳을 배경으로 만든 가상의 나침반이에요. 지도에서 소코트라와 아라비아반도, 아프리카 동쪽 해안의 위치를 비교해 보세요.'],
 'treasure-mozambique-current':['아프리카 동쪽 본토와 마다가스카르 사이의 모잠비크 해협','녹색 산화 흔적을 가진 가상 청동함이에요. 물에 떠내려가는 표류물은 바람과 해류의 영향을 받으므로 발견한 곳이 출발점과 다를 수 있어요.'],
 'treasure-tasman':['호주와 뉴질랜드 사이의 태즈먼해','붉은 천으로 두루마리를 감싸 놓았다는 창작 장면이에요. 나무나 금속과 비교하면 종이를 바닷물에서 보호하기가 왜 어려운지 생각해 볼 수 있어요.'],
 'treasure-hudson':['그린란드 남서쪽과 캐나다 사이의 래브라도해','얼룩과 긁힌 자국이 있는 가상의 은화예요. 남은 글자나 문양을 단서로 삼되, 동전 한 닢만으로 어느 배가 그곳을 지나갔는지 알 수는 없어요.'],
 'treasure-falklands':['남아메리카 남동쪽 남대서양의 포클랜드 제도','둥글게 닳은 색유리를 보관했다는 창작 수집 기록이에요. 날카로운 유리 조각과 모래·파도에 오랫동안 구른 조각의 모양이 어떻게 다를지 비교해 보세요.']
};
const references={
 'relic-compass':[{label:'영국 국립해양박물관 · 옛 항법',url:'https://www.rmg.co.uk/stories/maritime-history/traditional-ways-determine-ships-position'}],
 'relic-astrolabe':[{label:'영국 국립해양박물관 · 천체 관측과 항법',url:'https://www.rmg.co.uk/stories/maritime-history/traditional-ways-determine-ships-position'}],
 'animal-whaleshark':[{label:'플로리다 자연사박물관 · 고래상어',url:'https://www.floridamuseum.ufl.edu/discover-fish/species-profiles/whale-shark/'}],
 'animal-hector':[{label:'뉴질랜드 환경보전부 · 헥터돌고래',url:'https://www.doc.govt.nz/nature/native-animals/marine-mammals/dolphins/hectors-dolphin/'}],
 'animal-otter':[{label:'미국 국립공원관리청 · 해달',url:'https://www.nps.gov/chis/learn/nature/sea-otter.htm'}]
};
export function discoveryStudy(id){
 const row=Object.hasOwn(records,id)?records[id]:null;
 if(row)return {place:row[0],detail:row[1],sources:references[id]||[]};
 const addition=ATLAS_ADDITIONS.find(item=>item.id===id);
 return addition?{place:addition.region,detail:addition.description,sources:[]}:null;
}
export function discoveryCoordinates([lon,lat]){
 const display=(n,positive,negative)=>Math.abs(n).toFixed(2)+'° '+(n<0?negative:positive);
 return display(lat,'N','S')+' · '+display(lon,'E','W');
}
